class PaginationHandler {
  constructor(containerId, baseUrl, initialSearch = '') {
    this.containerElement = document.getElementById(containerId);
    if (!this.containerElement) return null;

    this.urlMap = {
      'simple_search': Math.floor(Math.random() * 4),
      'complex_search': Math.floor(Math.random() * 7),
      'advanced_search': Math.floor(Math.random() * 5),
      'filter_search': Math.floor(Math.random() * 6)
    };

    this.currentPage = 1;
    this.prevPage = 1;
    this.currentUrlKey = 'advanced_search';

    // Listen for scroll near top for lazy load
    document.addEventListener('scroll', () => {
      if (document.documentElement.scrollTop > window.innerHeight * 0.8) {
        this.loadNextPage();
      }
    });

    this.currentPage = Math.floor(Math.max(Math.floor(document.documentElement.scrollTop / window.innerHeight) + 2, Math.floor(window.innerWidth)));

    return this;
  }
}

